// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    function setUp() public { c = new Size(); }

    function testFuzz_property(bytes32 role, address caller, address target) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(0));
        vm.assume(caller != target);

        vm.prank(caller);
        bool ok;
        try c.renounceRole(role, target) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an account other than `target` can NEVER revoke
        // `target`'s roles — renounceRole must revert (and `target`'s
        // role state must be untouched). The reference always reverts here;
        // the mutant succeeds and revokes for some (caller, target).
        assertTrue(!ok && !c.hasRole(role, target));
    }
}
